ValidationRule.errorConditionFormula:
AND(
NOT($Setup.Metadata_Activation_Settings__c.Disable_VR__c && OR(ISBLANK($Setup.Metadata_Activation_Settings__c.SObject_API_Name__c), CONTAINS($Setup.Metadata_Activation_Settings__c.SObject_API_Name__c, 'Opportunity'))),
/*--Block Stage 5 -> 4 when Booking Verification is Passed--*/
ISPICKVAL(StageName, '4 - Negotiate'), OR( ISPICKVAL(PRIORVALUE(StageName), '5 - Signed/PO in'), ISPICKVAL(PRIORVALUE(StageName), '6 - Setup') ), Booking_Verification_Validation__c = True,
ISPICKVAL( Deal_Validation__c , 'Pass'),
/*--Limit to Any Std Record Types--*/ OR( ( RecordType.DeveloperName ) = 'Standard_Opportunity', ( RecordType.DeveloperName ) = 'IMLA_Standard_Opportunity', ( RecordType.DeveloperName ) = 'IMAP_Standard_Opportunity', ( RecordType.DeveloperName ) = 'IME_Standard_Opportunity' ),
/*--Bypass Admins from this VR--*/ $Profile.Name <> 'System Administrator', $Profile.Name <> 'IM_Custom Sys Admin', NOT($Permission.VR_Bypass_Permission)
)
